from math import ceil
from typing import List


def count_set_bits_and_ones(x: int) -> tuple[tuple[int], int]:
    i = ceil(0.1 * x + 0.05)
    count = 0
    while x % 2 == 0:
        x //= 2
        count += 1
    if count & 1:
        count += 1
    return count, i


class DigitOperations:
    def __init__(self, order):
        self.power_basis = 2**order - 2

    def power_weight(self, base: int, exponent: int) -> int:
        power = base**exponent
        if power >= self.power_basis:
            return power - self.power_basis
        return 0

    def count_left_over_count(self, value_count: int) -> tuple[tuple[int], int]:
        assert value_count >= 0
        count, left_over = count_set_bits_and_ones(value_count)
        curr, total = self.power_weight(self.power_basis - 1, count), self.power_weight(self.power_basis - 1, count + 1)
        if value_count > curr:
            r = value_count - curr - 1
            r_idx = r.bit_length() - 1
            total += self.power_weight(self.power_basis, r_idx)
        return count, left_over


