from heapq import heappush, heappop
from collections import defaultdict

def find_lowest_free_cell(cells):
    """Find the lowest free cell with the lowest number."""
    free_cells = []
    for cell, pocket in enumerate(cells, 1):
        if pocket > 0:
            free_cells.append((cell, len(cells)))

    # Sort cells by their number
    free_cells.sort()
    return min(free_cells, key=lambda x: (x[0], -x[1]))

def process_pocket_operations(pockets, operations):
    """Handle operations on pockets at cells a_1, …, a_n."""
    for _ in range(operations):
        opened_pockets = pockets.copy()
        opened_pockets[:n] = [0] * n
        for i in range(len(opened_pockets) - 1, -1, -1):
            if opened_pockets[i]:
                opened_pockets[i + 1] += 1
        return opened_pockets

def filter_balls(k, pocket_positions, balls):
    """Simulate the filtering process."""
    balls = [-ball for ball in balls]
    for _ in range(k):
        # Process pockets simultaneously
        pocket_positions = process_pocket_operations(pocket_positions, len(pocket_positions))
        # Move breaking balls to lowest free cell
        for pos, pocket in enumerate(pocket_positions):
            if pocket:
                index = heappop(balls)
                if index < len(balls) + 1:
                    pocket_positions[pos] -= 1
                elif pockets[pos] > 0:
                    pocket_positions[pos] -= pockets[pos] + 1
                elif pocket_positions[-1] > holes[pos]:
                    pocket_positions[pos] -= pockets[pos] + -holes[pos]
                    heappush(balls, 0)
                elif not balls:
                    return readings[pos]
            if pocket:
                pocket_positions[pos] = max(0, pocket_positions[pos])
    return -balls[0]

