from math import inf

def max_fraction_weighted_components(n, weights, edges):
    graph = [[] for _ in range(n + 1)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    components = []
    visited = [False] * (n + 1)
    sum_weights = [0] * (n + 1)
    component_size = [0] * (n + 1)

    def dfs(node, parent=None):
        visited[node] = True
        component = Fraction(weights[node], 1).limit_denominator()
        min_weight = component // 2
        component_size[node] = 1
        min_size = 0
        for neighbor in graph[node]:
            if visited[neighbor] and neighbor != parent:
                min_size = max(min_size, component_size[neighbor])
        component_size[node] += min_size
        if min_size > 0:
            fraction = Fraction(min_weight, 2).limit_denominator()
            if component > fraction:
                return False
        return True

    def dfs_adjacent(node, parent=None):
        visited[node] = True
        component = Fraction(weights[node], 1).limit_denominator()
        max_size = 1
        for neighbor in graph[node]:
            if visited[neighbor] and neighbor != parent:
                max_size = max(max_size, dfs_adjacent(neighbor, node))
        return max_size

    def build_components(graph):
        for node in range(1, n + 1):
            if not visited[node]:
                dfs(node, None)
                components.append([Fraction(w, 1).limit_denominator() for w in sum_weights][1:])
                for i in range(n + 1):
                    sum_weights[i] = sum(sum_weights[i][1:] + [sum_weights[i][0]])
        for component in components:
            root = dfs_adjacent(0)
            total_size = len(component) * root
            max_total_size = 0
            for component in components:
                valid = len(component) * (component[0] - max_w)
                if valid > total_size:
                    max_total_size = valid
                    min_weight = min_w
                elif valid == total_size and min_weight > component[0] - max_w:
                    min_weight = component[0] - max_w
            components[components.index(component)] = [Fraction(min_weight, 1).limit_denominator()]
        return components

    return build_components(graph)

