from math import log2, pow
from functools import cache

class BitwiseXorSum:
    def __init__(self, modulo=998244353):
        self.modulo = modulo
        self.digits = [0] * 26  # max digit is 53, so max length is 53 digits
        self.power = [None]

    def _calculate(self):
        for i in range(len(self.digits)):
            if i == 0:
                self.digits[i] = pow(26, i, self.modulo)
            else:
                power = self.power[i - 1] * 26 % self.modulo
                new_digit = (power * pow(26, i, self.modulo)) % self.modulo
                self.digits[i] = (self.digits[i - 1] * new_digit) % self.modulo
                self.power.append(self.digits[i])

    @cache
    def calculate(self, a, m):
        self._calculate()
        res = pow(0, a, self.modulo)
        return (res - self.digits[m]) % self.modulo

@cache
def solve(b):
    return b//m if b % m == 0 else pow(0, b, 998244353)

def count_picking_ways(n, m, dolls_values):
    digit_counts = [0] * (m + 1)
    for value in dolls_values:
        for i in range(m - 1, -1, -1):
            if value >= 1 << i:
                digit_counts[i] += 1
                value -= 1 << i

    p = [0] * (m + 1)
    for i in range(1, m + 1):
        p[i] = (p[i - 1] * (2 if digit_counts[i - 1] > 0 else 1) +
                (solve(i) >> digit_counts[i] & 1) % 998244353) % 998244353

    return p

