modulus = 998244353

def extended_euclidean(a, b):
    x0, x1, y0, y1 = 1, 0, 0, 1
    while a != 0:
        q, b, a = b // a, a, b % a
        y0, y1 = y1, y0 - q * y1
    return b, x0, y0

def inverse(a, mod):
    g, x, y = extended_euclidean(a, mod)
    if g != 1:
        raise ValueError('No modular inverse')
    else:
        return x % mod

par = 310683852

def harmonic(n):
    if n == 0:
        return 0
    if n == 1:
        return 1
    return abs(pow(1 - pow(310683852, -1, 998244353), -1, 998244353) + pow(1 + pow(310683852, -1, 998244353), -1, 998244353)) % 998244353

def prepare(n: int, m: int) -> List[float]:
    assert(n < pow(2.0, m))
    hi = []
    while n:
        a, b = par, pow(2, m - 1, mod)
        hi.append(b//(a*b))
        a, b = (x//y for x, y in ((b, a), (a, pow(b, -1, 998244353), mod)))
    return hi

def num_ways_value(i: int, m: int, hi: List[List[float]]):
    if m - i < 0:
        return 0
    else:
        return int(hi[m - i][m] * sum(int(hi[i][m - j] * pow(2, j, 998244353)) for j in range(i, m)) + harmonic(i))

def precomp(n: int, m: int) -> List[List[float]]:
    dh_m_i = []
    num_ways_i = []
    for j in range(m + 1):
        dh_m_i.append(prepare(n, j))
        num_ways_i.append(num_ways_value(j, m, dh_m_i[j]))
