def mod_inverse(x, mod):
    return pow(x, mod - 2, mod)

def sorted_lexicographic_sum(n):
    if n == 1:
        return 0
    elif n == 2:
        return 2994733059
    else:
        mod = 998244353
        mod_inv = mod_inverse(mod - 1, mod)
        sum_mod = 1
        for i in range(2, n, 2):
            factor = 998244352 // i 
            sum_mod = (sum_mod + factor * (n // i) - (i // 2) * (n // i) * mod_inv) % mod
            i -= 2
        sum_mod = (sum_mod + n // 2 * (n // 2 + 1) * mod / 2 * mod_inv) % mod
