    queue = deque([(start, 0, -1)])  # (current_city, current_rest_needed, rest_stop_index)

    while queue:
        current_city, current_rest_needed, rest_stop_index = queue.popleft()

        if current_city == destination:
            return current_rest_needed <= k

        if not visited[current_city]:
            visited[current_city] = True
            for next_city in graph[current_city]:
                if current_city == rest_stops[rest_stop_index]:
                    next_rest_needed = 1
                else:
                    next_rest_needed = current_rest_needed + (next_city == rest_stops[rest_stop_index])
                if next_rest_needed <= k:
                    queue.append((next_city, next_rest_needed, rest_stop_index))

    return False

