from math import factorial

def generate_lucky_tickets(length, base):
    lucky_numbers = list(range(base * base))
    for i in range(1, length):
        if (base * base)**i <= len(lucky_numbers) and (base * base) > 0:
            lucky_numbers += list(range((base * base)**i, (base * base)**i + len(lucky_numbers)))

    lucky_tickets = '.' + ''.join(str(n) for n in lucky_numbers[(length - 1)::-1])
    return lucky_tickets.replace('..', '')

def find_k_lucky_tickets(k, m):
    tickets = {}
    for length in range(1, max(k) + 1):
        for candidates in itertools.combinations(range(int(factorial(length) / 2)), k):
            ticket = ''.join(map(str, [a+b for a, b in zip(candidates, range(k, 0, -1))]))
            if ticket in tickets:
                tickets[ticket] += 1
            else:
                tickets[ticket] = 1
    return [kicket for kicket in tickets][:m]

