from math import comb

def recover_departments(employees, contacts):
    N = len(employees)
    departments = [0] * N
    heads = [0] * N

    if N == len(contacts):
        return departments, heads

    num_departments = comb(N, 2)

    for i in range(2, num_departments + 1):
        if len(set(departments)) == num_departments or len(set(departments + heads)) == num_departments:
            for j in range(i):
                if departments[j] == 0 and heads[j] == 0:
                    for _, pair in enumerate(contacts):
                        if employees[i - 1] in pair and pair[1] != employees[i - 1]:
                            departments[i - 1] = pair[0]
                            heads[i - 1] = pair[1]
                            break
                        elif employees[i - 1] == pair[0] and pair[1] != employees[i - 1]:
                            departments[i - 1] = pair[1]
                            heads[i - 1] = pair[0]
                            break
                    break

    for i in range(N):
        if departments[i] == 0:
            departments[i] = 1

    for i in range(N):
        if heads[i] == 0:
            heads[i] = i + 1

    return departments, heads

# Example usage
T = int(input())
