from sympy import mod_inverse

def count_tours(k, l, r):
    MOD = 10**9 + 7

    def factorial(n):
        return comb(n + k - 1, k)

    def inverse_factorial(n):
        return mod_inverse(factorial(n), MOD)

    if k == 1:
        return r - l + 1
    else:
        return divmod(mod_product(l, r - 1, MOD - 1), k - 1, k) + mod_product((r - 1) // k, MOD - 1, MOD - 1)

